// Answering Understand's questions from the Work list and Home (Code #1057), through Cloud's real handler, against a pretend Code that answers only with Code's REAL answers
// (tests/fixtures/code-inline-understand.json, generated by running Code's own handlers in a fresh clone of #1057's tree; see its `_about`):
//   1. The Work list (`GET /v1/app/sessions`, Code's `?detail=1`) passes each row's Understand round and workflow outcome on as Code sent them, and nothing in another shape.
//   2. `POST /v1/app/tasks/{taskId}/answers` checks the session page's body and sends Code only the request id, round and answers, as the person; Code's refusals pass through.
// Auth negatives: a member of the company who may neither read nor act on the task, and a person of another company. Cloud decides neither: Code's own answers reach them.
import { describe, expect, it } from "vitest";
import { CodeClient, LocalSessionStore, LocalWorkSessionStore, createCloudHandler, type CloudRequest, type CodeSession } from "../../packages/cloud-server/src/index.js";
import { roundOf, workTask } from "../../packages/cloud-server/src/work-reads.js";
import { ANSWERS_REFUSED } from "../../packages/cloud-server/src/answers.js";
import { INLINE_UNDERSTAND as F, type Answer } from "../fixtures/code-inline-understand.js";

type Obj = Record<string, unknown>;
const CODE = "https://code.example.test";
const ORIGIN = "https://cloud.example.test";
const NOW = Date.UTC(2026, 10, 18, 12);
const ADA = "a".repeat(64), SAM = "b".repeat(64), EVE = "e".repeat(64);
const json = (status: number, body: unknown) => new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json" } });
const NOT_SERVED: Answer = { status: 404, body: { error: { code: "NOT_FOUND", message: "route not found" } } };
const b64 = (value: unknown) => Buffer.from(JSON.stringify(value)).toString("base64url");
const tokenOf = (who: string) => { const nowS = Math.floor(NOW / 1000);return `${b64({ alg: "RS256", typ: "JWT" })}.${b64({ sub: who, iat: nowS, exp: nowS + 3600, jti: who })}.c2ln`; };
const ANSWERS = [{ questionId: "q1", optionId: "b" }, { questionId: "q2", text: "Leave the database alone." }];
const BODY = { requestId: F.requestId, round: F.round, revision: F.revision, answers: ANSWERS };

interface Call { method: string; path: string; search: string; who: string; body: unknown }
type Code = (call: Call) => Answer | undefined;

function setUp(code: Code) {
  const calls: Call[] = [];
  const people = new Map<string, string>();
  const fetchImpl = (async (input: string | URL | Request, init?: RequestInit) => {
    const url = new URL(input instanceof Request ? input.url : input);
    const token = ((init?.headers ?? {}) as Record<string, string>).authorization?.replace(/^Bearer /u, "") ?? "";
    const call: Call = { method: init?.method ?? "GET", path: url.pathname, search: url.search, who: people.get(token) ?? "nobody", body: typeof init?.body === "string" ? JSON.parse(init.body) : undefined };
    calls.push(call);
    if (url.pathname === "/v1/auth/token") return json(400, { error: "invalid_grant" });
    const answer = code(call) ?? NOT_SERVED;
    return json(answer.status, answer.body);
  }) as typeof fetch;
  const store = new LocalSessionStore(undefined, { environment: {} });
  const work = new LocalWorkSessionStore();
  const client = new CodeClient({ baseUrl: CODE, clientId: "rovara-cloud", clientSecret: "secret", redirectUri: "http://127.0.0.1:8787/callback", scopes: "", fetch: fetchImpl });
  const handler = createCloudHandler({ client, store, work, origin: ORIGIN, org: { orgId: "acme", name: "Acme", plan: "test" }, callbackPath: "/callback", secureCookies: true, log: () => undefined, now: () => new Date(NOW) });
  const signIn = async (who: "ada" | "sam" | "eve") => {
    const developerId = who === "ada" ? ADA : who === "sam" ? SAM : EVE;
    const token = tokenOf(who);
    people.set(token, who);
    const access: CodeSession["access"] = { developerId, displayName: who, administrator: false, projects: who === "eve" ? [] : [{ name: "payments", access: "developer" }], notices: [] };
    await store.create(`cookie-${token}`, { accessToken: token, refreshToken: `r-${who}`, csrf: "csrf", signedInAt: new Date(NOW).toISOString(), access });
    return { cookie: `rovara_cloud_session=cookie-${token}`, "x-rovara-csrf": "csrf", origin: ORIGIN };
  };
  const send = async (method: string, target: string, body: unknown, headers: Record<string, string>) => {
    const url = new URL(target, "http://127.0.0.1:8787");
    const request: CloudRequest = { method, path: url.pathname, query: url.searchParams, headers: { ...headers, "content-type": "application/json" }, ...(body === undefined ? {} : { body: JSON.stringify(body) }) };
    const answered = (await handler(request))!;
    return { status: answered.status, body: JSON.parse(answered.body) as Obj & { error?: { code: string; message: string }; tasks?: Obj[] } };
  };
  const asked = (pattern: RegExp) => calls.filter((call) => call.path !== "/v1/auth/token" && pattern.test(`${call.method} ${call.path}`));
  return { send, signIn, calls, asked };
}

const LIST = "/v1/web/sessions", ANSWER = (taskId: string) => `/v1/web/tasks/${taskId}/answers`;
const codeRow = (answer: Answer, taskId: string) => (answer.body["tasks"] as Obj[]).find((row) => row["taskId"] === taskId)!;

describe("1. the Work list passes Code's Understand round and outcome on", () => {
  it("the fixture is what Cloud expects: a waiting round with an option question (recommended marked) and a free-text one, then all answered; a CLOSED outcome; no round for no access or another company", () => {
    expect(codeRow(F.waitingList, F.taskId)["round"]).toMatchObject({ round: 1, questions: [{ id: "q1", recommended: "b", answered: false }, { id: "q2", answered: false }] });
    expect(codeRow(F.answeredList, F.taskId)["round"]).toMatchObject({ questions: [{ answered: true }, { answered: true }] });
    expect(codeRow(F.closedList, F.closedTaskId)["outcome"]).toBe("CLOSED");
    expect(codeRow(F.noAccessList, F.noAccessTaskId)["round"]).toBeUndefined();
    expect(F.otherCompanyList.body).toEqual({ tasks: [] });
  });

  it("the owner's list: the round exactly as Code sent it, and the row's workflow revision the answers need", async () => {
    const w = setUp((call) => (call.path === "/v1/dev/tasks" && call.who === "ada" ? F.waitingList : undefined));
    const list = await w.send("GET", LIST, undefined, await w.signIn("ada"));
    expect(list.status).toBe(200);
    const row = list.body.tasks!.find((task) => task["taskId"] === F.taskId)!;
    expect(row["round"]).toEqual(codeRow(F.waitingList, F.taskId)["round"]);
    expect(row["workflow"]).toMatchObject({ stage: "UNDERSTAND", state: "WAITING", revision: F.revision });
    expect(row["outcome"]).toBeUndefined();
    expect(w.asked(/^GET \/v1\/dev\/tasks$/u)[0]!.search).toContain("detail=1");
    // For these rows Cloud's answer is Code's row, less `shared: false` (said only when true) and with an empty pull request list: the web tests draw Code's rows as they are (tests/web/work-inline-understand.test.ts).
    const { shared, ...rest } = codeRow(F.waitingList, F.taskId);
    expect(shared).toBe(false);
    expect(row).toEqual({ ...rest, pullRequests: [] });
  });

  it("a finished task's outcome is on its row; Code's rows for someone it shows no round, and another company's empty list, have none", async () => {
    const w = setUp((call) => (call.path !== "/v1/dev/tasks" ? undefined : call.who === "ada" ? F.closedList : call.who === "sam" ? F.noAccessList : F.otherCompanyList));
    const closed = (await w.send("GET", LIST, undefined, await w.signIn("ada"))).body.tasks!;
    expect(closed.find((task) => task["taskId"] === F.closedTaskId)).toMatchObject({ outcome: "CLOSED", workflow: { stage: "CLOSED", state: "COMPLETE" } });
    expect(closed[0]!["round"]).toBeUndefined();
    expect(closed[0]).toEqual({ ...Object.fromEntries(Object.entries(codeRow(F.closedList, F.closedTaskId)).filter(([key]) => key !== "shared")), pullRequests: [] });
    const sam = (await w.send("GET", LIST, undefined, await w.signIn("sam"))).body.tasks!;
    expect(sam).toHaveLength(1);
    expect(JSON.stringify(sam)).not.toMatch(/"round"|health check/u);
    const eve = await w.send("GET", LIST, undefined, await w.signIn("eve"));
    expect(eve.body).toEqual({ tasks: [] });
  });

  it("a round or outcome in any other shape is left out whole (never part of a round)", () => {
    const real = codeRow(F.waitingList, F.taskId)["round"] as { round: number; questions: Obj[] };
    expect(roundOf(real)).toEqual(real);
    const q = (change: Obj) => ({ ...real, questions: [{ ...real.questions[0]!, ...change }, real.questions[1]!] });
    for (const bad of [
      undefined, null, [], "round", { ...real, round: 0 }, { ...real, round: 1.5 }, { ...real, round: "1" }, { ...real, questions: [] }, { ...real, questions: [...real.questions, ...real.questions] },
      { ...real, questions: [real.questions[0], real.questions[0]] }, q({ id: "q4" }), q({ text: "" }), q({ text: "x".repeat(301) }), q({ answered: "no" }), q({ answered: undefined }),
      q({ options: [{ id: "a", label: "only one" }] }), q({ options: [{ id: "e", label: "x" }, { id: "a", label: "y" }] }), q({ options: [{ id: "a", label: "" }, { id: "b", label: "y" }] }),
      q({ recommended: "c" }), { ...real, round: 1_000_001 }, q({ options: ["a", "b", "c", "d", "a"].map((id, n) => ({ id, label: String(n) })) }), q({ options: [{ id: "a", label: "x".repeat(81) }, { id: "b", label: "y" }] }), q({ recommended: 1 }), { ...real, questions: [{ ...real.questions[1]!, recommended: "a" }] }, { ...real, questions: [null] },
    ]) expect(roundOf(bad), JSON.stringify(bad)).toBeUndefined();
    const row = codeRow(F.closedList, F.closedTaskId);
    expect(workTask({ ...row, outcome: "DONE" })!["outcome"]).toBeUndefined();
    expect(workTask({ ...row, outcome: 3 })!["outcome"]).toBeUndefined();
    expect(workTask(row)!["outcome"]).toBe("CLOSED");
    for (const outcome of ["PASSED", "SKIPPED", "CHANGES_REQUESTED", "REJECTED", "MERGED", "CLOSED", "ANSWERED"]) expect(workTask({ ...row, outcome })!["outcome"]).toBe(outcome);
    expect(roundOf({ ...real, round: 1_000_000 })).toEqual({ ...real, round: 1_000_000 });
    expect(roundOf({ ...real, questions: [{ ...real.questions[0]!, options: ["a", "b", "c", "d"].map((id) => ({ id, label: "x".repeat(80) })) }] })).toBeDefined();
    expect(workTask({ ...codeRow(F.waitingList, F.taskId), round: { ...real, round: 0 } })!["round"]).toBeUndefined();
  });
});

describe("2. POST /v1/app/tasks/{taskId}/answers", () => {
  it("the owner's answers go to Code's answers route as the owner, with only the request id, round and answers; Cloud says they were taken, and the next list says every question is answered", async () => {
    let answered = false;
    const w = setUp((call) => {
      if (call.method === "POST" && call.path === `/v1/dev/tasks/${F.taskId}/answers` && call.who === "ada") { answered = true;return F.accepted; }
      if (call.path === "/v1/dev/tasks" && call.who === "ada") return answered ? F.answeredList : F.waitingList;
      return undefined;
    });
    const ada = await w.signIn("ada");
    const sent = await w.send("POST", ANSWER(F.taskId), { ...BODY, extra: "dropped" }, ada);
    expect(sent).toEqual({ status: 200, body: { taskId: F.taskId, answered: true } });
    const forwarded = w.asked(/^POST \/v1\/dev\/tasks\/.+\/answers$/u);
    expect(forwarded).toHaveLength(1);
    expect(forwarded[0]).toMatchObject({ who: "ada", path: `/v1/dev/tasks/${F.taskId}/answers`, body: { requestId: F.requestId, round: F.round, answers: ANSWERS } });
    expect(Object.keys(forwarded[0]!.body as Obj).sort()).toEqual(["answers", "requestId", "round"]);
    // Cloud reads no task and keeps nothing of its own for this answer.
    expect(w.asked(/^GET /u)).toHaveLength(0);
    const after = (await w.send("GET", LIST, undefined, ada)).body.tasks!.find((task) => task["taskId"] === F.taskId)!;
    expect(after["round"]).toEqual(codeRow(F.answeredList, F.taskId)["round"]);
    expect(after["workflow"]).toMatchObject({ state: "READY", revision: F.revision + 1 });
  });

  it("a task id in capitals is Code's lower-case id; anything that is not a task id is not a route here, and Code is not asked", async () => {
    const w = setUp((call) => (call.method === "POST" && call.path === `/v1/dev/tasks/${F.taskId}/answers` ? F.accepted : undefined));
    const ada = await w.signIn("ada");
    expect((await w.send("POST", ANSWER(F.taskId.toUpperCase()), BODY, ada)).status).toBe(200);
    expect(w.asked(/answers$/u).map((call) => call.path)).toEqual([`/v1/dev/tasks/${F.taskId}/answers`]);
    for (const id of ["not-a-task", `${F.taskId}x`, "../tasks", encodeURIComponent(`${F.taskId}/answers`)]) expect((await w.send("POST", ANSWER(id), BODY, ada)).status).toBe(501);
    expect(w.asked(/answers$/u)).toHaveLength(1);
  });

  it("a body that is not the answer form's is refused in fixed words, and Code is not asked", async () => {
    const w = setUp(() => F.accepted);
    const ada = await w.signIn("ada");
    for (const [body, words] of [
      [[1], ANSWERS_REFUSED.body], [{ ...BODY, requestId: "x" }, ANSWERS_REFUSED.requestId], [{ ...BODY, round: 0 }, ANSWERS_REFUSED.round], [{ ...BODY, revision: -1 }, ANSWERS_REFUSED.revision],
      [{ ...BODY, answers: [] }, ANSWERS_REFUSED.list], [{ ...BODY, answers: [{ questionId: "q9", optionId: "a" }] }, ANSWERS_REFUSED.answer], [{ ...BODY, answers: [{ questionId: "q1", text: "" }] }, ANSWERS_REFUSED.text],
    ] as const) {
      const refused = await w.send("POST", ANSWER(F.taskId), body, ada);
      expect(refused, JSON.stringify(body)).toEqual({ status: 400, body: { error: { code: "CONFIG_INVALID", message: words } } });
    }
    expect(w.asked(/answers$/u)).toHaveLength(0);
  });

  it("Code's 'not waiting' (the same round again, or a round Code is not on) reaches the page with its code, so the form says the questions were already answered", async () => {
    const w = setUp((call) => (call.method === "POST" ? ((call.body as { round: number }).round === 2 ? F.wrongRound : F.staleAnswer) : undefined));
    const ada = await w.signIn("ada");
    expect(await w.send("POST", ANSWER(F.taskId), BODY, ada)).toEqual({ status: 409, body: F.staleAnswer.body });
    expect(await w.send("POST", ANSWER(F.taskId), { ...BODY, round: 2 }, ada)).toEqual({ status: 409, body: F.wrongRound.body });
    expect((F.staleAnswer.body["error"] as Obj)["code"]).toBe("INTENT_NOT_WAITING");
  });

  it("auth: a member Code lets neither read nor act on the task, and another company's person, get Code's own no-such-task answer; Cloud adds nothing", async () => {
    const w = setUp((call) => {
      if (call.method !== "POST") return undefined;
      if (call.who === "sam" && call.path === `/v1/dev/tasks/${F.noAccessTaskId}/answers`) return F.noAccessAnswer;
      if (call.who === "eve" && call.path === `/v1/dev/tasks/${F.taskId}/answers`) return F.otherCompanyAnswer;
      return { status: 500, body: { error: { code: "WRONG", message: "unexpected" } } };
    });
    const sam = await w.send("POST", ANSWER(F.noAccessTaskId), { ...BODY, requestId: "55555555-5555-4555-8555-555555555555" }, await w.signIn("sam"));
    expect(sam).toEqual({ status: 404, body: F.noAccessAnswer.body });
    const eve = await w.send("POST", ANSWER(F.taskId), { ...BODY, requestId: "11111111-1111-4111-8111-111111111111" }, await w.signIn("eve"));
    expect(eve).toEqual({ status: 404, body: F.otherCompanyAnswer.body });
    expect(w.asked(/answers$/u).map((call) => call.who)).toEqual(["sam", "eve"]);
  });

  it("needs a signed-in person and the session's CSRF token: neither reaches Code", async () => {
    const w = setUp(() => F.accepted);
    const ada = await w.signIn("ada");
    expect((await w.send("POST", ANSWER(F.taskId), BODY, { origin: ORIGIN })).status).toBe(401);
    expect((await w.send("POST", ANSWER(F.taskId), BODY, { ...ada, "x-rovara-csrf": "wrong" })).status).toBe(403);
    expect(w.asked(/answers$/u)).toHaveLength(0);
  });
});
